84:    "mime"
85:    "autoindex"
86:    "negotiation"
87:    "dir"
88:    "alias"
89:    "rewrite"
90:    "unixd"
91:    "slotmem_shm"
92:    "socache_shmcb"
93:    "mpm_${cfg.mpm}"
94:  ]
95:  ++ (if cfg.mpm == "prefork" then [ "cgi" ] else [ "cgid" ])
